{"path":"neuron_growth_ollama-ornith-9b_01.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neuron Network Simulation</title>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background: #05070f;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            overflow: hidden;
            font-family: 'Courier New', monospace;
        }

        #canvas-container {
            position: relative;
            width: 800px;
            height: 800px;
            box-shadow: 0 0 60px rgba(0, 229, 255, 0.15);
        }

        canvas {
            display: block;
            width: 800px;
            height: 800px;
        }
    </style>
</head>
<body>
    <div id="canvas-container">
        <canvas id="neuronCanvas" width="800" height="800"></canvas>
    </div>

    <script>
        // ==================== SETUP ====================
        const canvas = document.getElementById('neuronCanvas');
        const ctx = canvas.getContext('2d');
        const WIDTH = canvas.width;
        const HEIGHT = canvas.height;

        const PALETTE = {
            background: '#05070f',
            backgroundGlow: '#101a3a',
            mainBranch: '#00e5ff',
            accentBranch: '#d6ff00',
            synapse: '#ff2bd6',
            pulse: '#fff36a',
            uiAccent: '#ffd400',
            grid: 'rgba(0, 229, 255, 0.08)',
        };

        // Neuron network state
        let neurons = [];
        let branches = [];
        let synapses = [];
        let pulses = [];
        let growing = true;

        // Growth parameters
        const growthParams = {
            neuronCount: 5,
            branchGrowthSpeed: 2,
            maxBranchDepth: 8,
            splitChance: 0.3,
            curvature: 0.3,
            maxBranchLength: 150,
        };

        // Synapse parameters
        const synapseParams = {
            distanceThreshold: 30,
            glowStrength: 0.6,
        };

        // Pulse parameters
        const pulseParams = {
            speed: 4,
            frequency: 0.02,
            brightness: 0.8,
        };

        // Visual parameters
        const visualParams = {
            backgroundColor: PALETTE.background,
            branchColor: PALETTE.mainBranch,
            accentBranchColor: PALETTE.accentBranch,
            synapseColor: PALETTE.synapse,
            pulseColor: PALETTE.pulse,
        };

        // ==================== GUI SETUP ====================
        const gui = new dat.GUI();

        gui.addFolder('Growth');
        gui.add(growthParams, 'neuronCount', 3, 6, 1).name('Neuron Count').onChange(initNetwork);
        gui.add(growthParams, 'branchGrowthSpeed', 1, 5).name('Branch Growth Speed');
        gui.add(growthParams, 'maxBranchDepth', 4, 15, 1).name('Max Branch Depth');
        gui.add(growthParams, 'splitChance', 0, 1).name('Split Chance');
        gui.add(growthParams, 'curvature', 0, 1).name('Curvature');
        gui.add(growthParams, 'maxBranchLength', 50, 300, 10).name('Max Branch Length');
        gui.addFolder('Synapses');
        gui.add(synapseParams, 'distanceThreshold', 10, 60, 5).name('Distance Threshold');
        gui.add(synapseParams, 'glowStrength', 0, 1).name('Glow Strength');
        gui.addFolder('Pulses');
        gui.add(pulseParams, 'speed', 1, 10).name('Speed');
        gui.add(pulseParams, 'frequency', 0, 0.05).name('Frequency');
        gui.add(pulseParams, 'brightness', 0, 1).name('Brightness');
        gui.addFolder('Visuals');
        gui.add(visualParams, 'backgroundColor', () => PALETTE.background).name('Background Color');
        gui.add(visualParams, 'branchColor', () => PALETTE.mainBranch).name('Branch Color');
        gui.add(visualParams, 'accentBranchColor', () => PALETTE.accentBranch).name('Accent Branch Color');
        gui.add(visualParams, 'synapseColor', () => PALETTE.synapse).name('Synapse Color');
        gui.add(visualParams, 'pulseColor', () => PALETTE.pulse).name('Pulse Color');

        gui.add({ regenerate: true, clear: true, pause: true }, 'regenerate').name('Regenerate Network').onChange(() => {
            neurons = [];
            branches = [];
            synapses = [];
            pulses = [];
            growing = true;
            initNetwork();
        });
        gui.add({ regenerate: true, clear: true, pause: true }, 'clear').name('Clear Canvas').onChange(() => {
            ctx.clearRect(0, 0, WIDTH, HEIGHT);
            growing = true;
            initNetwork();
        });
        gui.add({ regenerate: true, clear: true, pause: true }, 'pause').name('Pause/Resume').onChange(() => {
            if (!growing) {
                growing = true;
            }
        });

        // ==================== NEURON GROWTH ====================
        function initNetwork() {
            neurons = [];
            branches = [];
            synapses = [];
            pulses = [];

            const count = growthParams.neuronCount;
            const centerX = WIDTH / 2;
            const centerY = HEIGHT / 2;

            for (let i = 0; i < count; i++) {
                const neuron = {
                    x: centerX + (Math.random() - 0.5) * 150,
                    y: centerY + (Math.random() - 0.5) * 150,
                    radius: 3 + Math.random() * 2,
                    color: Math.random() > 0.5 ? PALETTE.mainBranch : PALETTE.accentBranch,
                    branchCount: 0,
                };
                neurons.push(neuron);
            }

            growing = true;
            requestAnimationFrame(animate);
        }

        class Branch {
            constructor(start, end, depth) {
                this.start = start;
                this.end = end;
                this.depth = depth;
                this.width = 1 + Math.random() * 2;
                this.color = Math.random() > 0.5 ? PALETTE.mainBranch : PALETTE.accentBranch;
            }

            draw() {
                const gradient = ctx.createLinearGradient(this.start.x, this.start.y, this.end.x, this.end.y);
                gradient.addColorStop(0, this.color);
                gradient.addColorStop(1, this.color);

                ctx.strokeStyle = gradient;
                ctx.lineWidth = this.width;
                ctx.lineCap = 'round';
                ctx.shadowBlur = 4;
                ctx.shadowColor = this.color;
                ctx.beginPath();
                ctx.moveTo(this.start.x, this.start.y);
                ctx.lineTo(this.end.x, this.end.y);
                ctx.stroke();
                ctx.shadowBlur = 0;
            }
        }

        function growBranches(neuron) {
            if (!growing || neuron.branchCount >= growthParams.maxBranchDepth) return;

            for (let i = 0; i < 3; i++) {
                const angle = Math.random() * Math.PI * 2;
                const length = Math.random() * growthParams.maxBranchLength * 0.6;
                const endX = neuron.x + Math.cos(angle) * length;
                const endY = neuron.y + Math.sin(angle) * length;

                const branch = new Branch(neuron, { x: endX, y: endY }, neuron.branchCount + 1);
                branches.push(branch);

                neuron.branchCount++;

                if (Math.random() < growthParams.splitChance && neuron.branchCount < growthParams.maxBranchDepth) {
                    const sideAngle = angle + (Math.random() - 0.5) * 0.5;
                    const sideLength = Math.random() * growthParams.maxBranchLength * 0.3;
                    const sideEndX = endX + Math.cos(sideAngle) * sideLength;
                    const sideEndY = endY + Math.sin(sideAngle) * sideLength;
                    const sideBranch = new Branch({ x: endX, y: endY }, { x: sideEndX, y: sideEndY }, neuron.branchCount + 1);
                    branches.push(sideBranch);
                }
            }
        }

        function detectSynapses() {
            const seen = new Set();
            for (let i = 0; i < neurons.length; i++) {
                for (let j = i + 1; j < neurons.length; j++) {
                    const dx = neurons[i].x - neurons[j].x;
                    const dy = neurons[i].y - neurons[j].y;
                    const dist = Math.sqrt(dx * dx + dy * dy);

                    if (dist < synapseParams.distanceThreshold) {
                        const key = i + '-' + j;
                        if (!seen.has(key)) {
                            seen.add(key);
                            synapses.push({
                                i,
                                j,
                                x: (neurons[i].x + neurons[j].x) / 2,
                                y: (neurons[i].y + neurons[j].y) / 2,
                                phase: Math.random() * Math.PI * 2,
                            });
                        }
                    }
                }
            }
        }

        // ==================== PULSE ANIMATION ====================
        function updatePulses() {
            const newPulses = [];
            const activePulses = [];

            for (let i = 0; i < synapses.length; i++) {
                const synapse = synapses[i];
                const neuron = neurons[synapse.i];
                const neighbor = neurons[synapse.j];

                if (Math.random() < pulseParams.frequency) {
                    activePulses.push({
                        start: neuron,
                        end: neighbor,
                        progress: Math.random(),
                        speed: pulseParams.speed + Math.random() * 2,
                        brightness: pulseParams.brightness,
                        color: PALETTE.pulse,
                    });
                }
            }

            for (const pulse of activePulses) {
                pulse.progress += pulse.speed * 0.01;
                if (pulse.progress > 1) pulse.progress = 0;

                const x = pulse.start.x + (pulse.end.x - pulse.start.x) * pulse.progress;
                const y = pulse.start.y + (pulse.end.y - pulse.start.y) * pulse.progress;

                newPulses.push({ x, y, ...pulse });
            }

            pulses = newPulses;
        }

        // ==================== RENDERING ====================
        function render() {
            ctx.fillStyle = visualParams.backgroundColor;
            ctx.fillRect(0, 0, WIDTH, HEIGHT);

            // Vignette effect
            const vignette = ctx.createRadialGradient(
                WIDTH / 2, HEIGHT / 2, HEIGHT * 0.4,
                WIDTH / 2, HEIGHT / 2, HEIGHT * 0.8
            );
            vignette.addColorStop(0, 'transparent');
            vignette.addColorStop(1, 'rgba(0, 0, 0, 0.6)');

            ctx.globalCompositeOperation = 'source-over';
            ctx.fillStyle = vignette;
            ctx.fillRect(0, 0, WIDTH, HEIGHT);
            ctx.globalCompositeOperation = 'source-over';

            // Draw branches
            branches.forEach(branch => branch.draw());

            // Draw synapses
            synapses.forEach(synapse => {
                const dx = neurons[synapse.i].x - neurons[synapse.j].x;
                const dy = neurons[synapse.i].y - neurons[synapse.j].y;
                const dist = Math.sqrt(dx * dx + dy * dy);
                const alpha = (1 - dist / synapseParams.distanceThreshold) * synapseParams.glowStrength;

                ctx.strokeStyle = PALETTE.synapse;
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = alpha;
                ctx.beginPath();
                ctx.arc(synapse.x, synapse.y, 3 + Math.sin(synapse.phase) * 1.5, 0, Math.PI * 2);
                ctx.stroke();
                ctx.globalAlpha = 1;
            });

            // Draw pulses
            pulses.forEach(pulse => {
                ctx.strokeStyle = pulse.color;
                ctx.lineWidth = 1.5;
                ctx.shadowBlur = 6;
                ctx.shadowColor = pulse.color;
                ctx.beginPath();
                ctx.arc(pulse.x, pulse.y, 2, 0, Math.PI * 2);
                ctx.stroke();
                ctx.shadowBlur = 0;
            });

            // Draw neurons
            neurons.forEach(neuron => {
                ctx.fillStyle = neuron.color;
                ctx.shadowBlur = 10;
                ctx.shadowColor = neuron.color;
                ctx.beginPath();
                ctx.arc(neuron.x, neuron.y, neuron.radius, 0, Math.PI * 2);
                ctx.fill();
                ctx.shadowBlur = 0;
            });

            // Subtle grid
            ctx.strokeStyle = PALETTE.grid;
            ctx.lineWidth = 0.5;
            for (let x = 0; x < WIDTH; x += 40) {
                ctx.beginPath();
                ctx.moveTo(x, 0);
                ctx.lineTo(x, HEIGHT);
                ctx.stroke();
            }
            for (let y = 0; y < HEIGHT; y += 40) {
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(WIDTH, y);
                ctx.stroke();
            }
        }

        // ==================== MAIN LOOP ====================
        function animate() {
            if (growing) {
                neurons.forEach(neuron => growBranches(neuron));
                detectSynapses();
            }
            updatePulses();
            render();
            requestAnimationFrame(animate);
        }

        // Initial setup
        initNetwork();
    </script>
</body>
</html>"}
